contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: amount to deposit, amount to collect
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // Ensure MinSum is 0 so that Collect can succeed when balance >= collectAmt
        // We call SetMinSum only if c is not initialized; this is allowed by public surface.
        // It's safe even if MinSum already set, because SetMinSum requires !intitalized in C;
        // if it reverts, we ignore and continue — we only need a path where Collect may succeed.
        // Do top-level calls that change state.
        // Try to set MinSum but do not catch revert; however per constraints any call that may revert should be handled.
        bool setMinOk;
        try c.SetMinSum(0) {
            setMinOk = true;
        } catch {
            setMinOk = false;
        }

        // Deposit depositAmt into c from this contract
        // ensure this contract has funds: caller of run must have funded this contract beforehand
        // transfer Ether to c by calling Deposit (payable) using value depositAmt
        require(address(this).balance >= depositAmt, "not enough balance for deposit");
        c.Deposit{value: depositAmt}();

        // read the caller balance before Collect (note: msg.sender for c calls is this contract)
        uint beforeBal = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        // attempt Collect and capture whether it reverted
        bool didRevert;
        try c.Collect(collectAmt) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint afterBal = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule: If Collect did not revert then the stored balance decreased by collectAmt
        // and the contract's Ether balance decreased by the same amount. If Collect reverted, no guarantees
        // are required by this property (but balances must not have increased beyond beforeBal).
        assert(
            // case: Collect succeeded -> exact decreases
            (!didRevert && beforeBal >= collectAmt && afterBal == (beforeBal - collectAmt) && contractBalAfter == (contractBalBefore - collectAmt))
            ||
            // case: Collect reverted -> stored balance unchanged (cannot increase) and contract balance unchanged
            (didRevert && afterBal == beforeBal && contractBalAfter == contractBalBefore)
        );
    }

    // allow receiving Ether so that the test harness can fund this contract
    receive() external payable {}
}

