    // It asserts that if Collect returns successfully then this contract's balance increased by exactly _am
    // and the stored balance for this contract decreased (i.e., did not increase).
    function run(uint dep, uint _am) public payable {
        require(address(this).balance >= dep);

        // record before-values
        uint beforeStored = c.balances(address(this));
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

