        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Initialize contract configuration while allowed
        c.SetMinSum(setMin);
        // Not setting LogFile and not calling Initialized() so contract remains configurable

        // Deposit funds to increase this contract's recorded balance in c
